pf:['Mineralogista.','Gemólogo/a.','Geólogo/a de exploración minera.'],
vc:['La sal, el yeso y el talco.','Los minerales del móvil y las baterías.','Las gemas y su certificación.'],
ac:[['Minerales críticos','Estrategias europeas de abastecimiento de litio, cobalto y tierras raras.'],['Silicosis por aglomerados de cuarzo','Problema laboral grave y regulación reciente.']],
