const BANCO = (() => {
  const nrm = s => ' ' + s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ]+/g, ' ').trim();
  const ENG = { A: 'Anécdota', P: 'Pregunta', C: 'Conexión cercana', R: 'Mini-reto' };
  const TIP = { I: 'Individual', P: 'Parejas', G: 'Grupo', C: 'Casa', L: 'Laboratorio', K: 'Campo' };
  return BANCO_RAW.map(t => ({ id: t.id, cursos: t.c, titulo: t.t, kw: [...new Set(t.kw.map(nrm).concat(nrm(t.t).split(' ').filter(w => w.length > 6).map(w => ' ' + w)))].map(k => k.trim().split(' ')),
    consejos: { analogias: t.an.map(([texto, limite]) => ({ texto, limite })), ejemplos: t.ej, errores: t.er.map(([error, detectar, corregir]) => ({ error, detectar, corregir })), dificultades: t.di.map(([que, estrategia]) => ({ que, estrategia })), preguntas: t.pr, vocabulario: t.vo.map(([termino, nota]) => ({ termino, nota })) },
    motivar: { enganche: t.en.map(([k, texto]) => ({ tipo: ENG[k], texto })), profesiones: t.pf, vida_cotidiana: t.vc, actualidad: t.ac.map(([tema, conexion]) => ({ tema, conexion })) },
    actividades: t.act.map(([titulo, descripcion, k, minutos]) => ({ titulo, descripcion, tipo: TIP[k], minutos })),
    recursos: t.rec.map(([tipo, titulo, descripcion, url]) => ({ tipo, titulo, descripcion, url })) }));
})();
